+    async fn handle_post_exec<G: Guest<Self>>(&self, guest: &mut G) -> Result<(), Errno> {
+        let mode = guest.config().mode;
+        assert_eq!(guest.regs().await.rip, ENTRY);
+        assert_eq!(word(guest, WORD), 0, "backend preinit executed guest entry");
