fn validate_liteinst_user_regs_update(
    current: &libc::user_regs_struct,
    requested: &libc::user_regs_struct,
) -> Result<(), Errno> {
    if current.rsp == requested.rsp {
        Ok(())
    } else {
        Err(Errno::ENOTSUPP)
    }
}

