        .send_signal(Signal::SIGKILL)
        .expect("kill child through pidfd");

    let mut info = std::mem::MaybeUninit::<libc::siginfo_t>::zeroed();
    let result = unsafe {
        libc::waitid(
            libc::P_PID,
            pid.as_raw() as libc::id_t,
