2095	            Err(HandleFailure::TraceError(e)) => return Err(e),
2096	            Err(HandleFailure::Event(wait)) => self.abort(Ok(wait)).await,
2097	            Ok(task) => task,
2098	        };
2099	        #[cfg(test)]
2100	        if let Some(sender) = self
2101	            .global_state
2102	            .liteinst_runtime
2103	            .as_ref()
2104	            .and_then(|runtime| runtime.pause_precise_timer_step.as_ref())
2105	        {
2106	            let _ = sender.send(task.pid());
2107	            future::pending::<()>().await;
2108	        }
2109	        self.process_state.clone().handle_timer_event(self).await;
2110	        self.timer.finalize_requests();
