2118	    ///  * running on the ptracer pthread
2119	    ///
2120	    /// Postconditions:
2121	    ///  * guest thread may or may not be stopped, depending on value of GuestNext
2122	    async fn handle_stop_event(&mut self, stopped: Stopped, event: Event) -> Result<Wait, Error> {
2123	        self.timer.observe_event();
2124	        let tid = self.tid();
2125	
2126	        #[cfg(test)]
2127	        if let Some((pause, sender)) = self
2128	            .global_state
2129	            .liteinst_runtime
2130	            .as_ref()
2131	            .and_then(|runtime| runtime.pause_root_stop.as_ref())
2132	        {
2133	            let selected = match &event {
2134	                Event::Seccomp => match pause {
2135	                    RootStopPause::Seccomp => true,
2136	                    RootStopPause::Signal(_) => false,
2137	                },
2138	                Event::Signal(actual) => match pause {
2139	                    RootStopPause::Seccomp => false,
2140	                    RootStopPause::Signal(expected) => expected == actual,
6090	            tracing::error!(%pid, "failed to notify orphan reaper while daemonizing tracee");
