 59	fn request_startup_timer<G: Guest<ClockTool>>(guest: &mut G, kind: u8) {
 60	    match kind {
 61	        0 => {}
 62	        1 => guest.set_timer_precise(TimerSchedule::Rcbs(1)).unwrap(),
 63	        2 => guest.set_timer(TimerSchedule::Rcbs(1)).unwrap(),
 64	        3 => guest
 65	            .set_timer_precise(TimerSchedule::RcbsAndInstructions(1, 2))
 66	            .unwrap(),
 67	        _ => panic!("unknown control timer kind"),
 68	    }
 69	}
