 71	#[reverie::tool]
 72	impl Tool for ClockTool {
 73	    type GlobalState = ClockLog;
 74	    type ThreadState = bool;
 75	
 76	    fn subscriptions(config: &Config) -> Subscription {
 77	        let mut events = Subscription::none();
 78	        events.syscalls([Sysno::getpid]);
 79	        if config.injected_exec {
 80	            events.syscalls([Sysno::execve]);
 81	        }
 82	        events
 83	    }
 84	
 85	    async fn handle_thread_start<G: Guest<Self>>(&self, guest: &mut G) -> Result<(), Error> {
 86	        assert!(guest.is_command_bootstrap());
 87	        let clock = guest.read_clock()?;
 88	        eprintln!("CLOCK_ORIGIN_TEST start={clock}");
 89	        assert_eq!(clock, 0);
 90	        guest.send_rpc(Observation::Start(clock)).await;
 91	        let kind = guest.config().startup_request;
 92	        request_startup_timer(guest, kind);
 93	        Ok(())
 94	    }
 95	
 96	    async fn handle_syscall_event<G: Guest<Self>>(
 97	        &self,
 98	        guest: &mut G,
 99	        call: Syscall,
100	    ) -> Result<i64, Error> {
101	        if call.number() == Sysno::execve {
102	            assert!(guest.is_command_bootstrap());
103	            let clock = guest.read_clock()?;
104	            eprintln!("CLOCK_ORIGIN_TEST intercepted_exec={clock}");
105	            assert_eq!(clock, 0, "the command launcher is outside guest accounting");
106	            guest.send_rpc(Observation::ExecCall(clock)).await;
107	            // This request is newer than handle_thread_start and exercises
108	            // the injected route's missing ordinary observe_event call.
109	            let kind = guest.config().startup_request;
110	            request_startup_timer(guest, kind);
111	            if guest.config().initial_failure {
112	                assert_eq!(guest.inject(call).await, Err(Errno::ENOENT));
113	                assert!(guest.is_command_bootstrap());
114	                assert!(!*guest.thread_state());
115	                let clock = guest.read_clock()?;
116	                eprintln!("CLOCK_ORIGIN_TEST failed_exec={clock}");
117	                assert_eq!(clock, 0, "failed initial exec did not activate the clock");
118	                guest.send_rpc(Observation::FailedExec(clock)).await;
119	                guest.tail_inject(Exit::default().with_status(27)).await
120	            }
121	            guest.tail_inject(call).await
122	        } else {
123	            assert_eq!(call.number(), Sysno::getpid);
124	            assert!(*guest.thread_state());
125	            let clock = guest.read_clock()?;
126	            eprintln!("CLOCK_ORIGIN_TEST boundary={clock}");
127	            guest.send_rpc(Observation::Boundary(clock)).await;
128	            Ok(guest.inject(call).await?)
129	        }
130	    }
131	
132	    async fn handle_post_exec<G: Guest<Self>>(&self, guest: &mut G) -> Result<(), Errno> {
133	        assert!(!guest.is_command_bootstrap());
134	        assert!(!*guest.thread_state());
135	        *guest.thread_state_mut() = true;
136	        let clock = guest
137	            .read_clock()
138	            .expect("post-exec clock must be available");
139	        eprintln!("CLOCK_ORIGIN_TEST post_exec={clock}");
140	        assert_eq!(
141	            clock, 0,
142	            "post-exec setup must not execute and rewind the entry branch"
143	        );
144	        assert_eq!(guest.regs().await.rip, 0x401000);
145	        guest.send_rpc(Observation::PostExec(clock)).await;
146	        // The real Tool callback is live immediately. A returned injected
147	        // syscall is not an initial command and does not reopen the hold.
148	        assert!(guest.inject(Getpid::default()).await? > 0);
149	        assert_eq!(guest.regs().await.rip, 0x401000);
150	        assert_eq!(
151	            guest.read_clock().expect("clock after post-exec injection"),
152	            0,
153	            "injection must not retire guest work"
154	        );
155	        if guest.config().post_exec_request {
156	            guest
157	                .set_timer_precise(TimerSchedule::Rcbs(1))
158	                .expect("new ordinary post-exec timer");
159	        }
160	        Ok(())
161	    }
162	
163	    async fn handle_timer_event<G: Guest<Self>>(&self, guest: &mut G) {
164	        assert!(
165	            *guest.thread_state(),
166	            "a timer fired in the excluded launcher interval"
167	        );
168	        assert!(
169	            guest.config().post_exec_request,
170	            "a retired initial request fired later"
171	        );
172	        let clock = guest.read_clock().unwrap();
173	        eprintln!("CLOCK_ORIGIN_TEST timer={clock}");
174	        guest.send_rpc(Observation::Timer(clock)).await;
175	    }
176	}
