259	    let fixture = Fixture::new(config.post_exec_request, config.initial_failure);
260	    let mut builder =
261	        TracerBuilder::<ClockTool>::new(Command::new(&fixture.0)).config(config.clone());
262	    builder.clock_test_launcher_branches = launcher_branches;
263	    let tracer = builder.spawn().await.unwrap();
264	    let (status, log) = tokio::time::timeout(Duration::from_secs(5), tracer.wait())
265	        .await
266	        .expect("initial-command control hung")
267	        .unwrap();
268	    assert_eq!(
269	        status,
270	        ExitStatus::Exited(if config.initial_failure { 27 } else { 0 })
271	    );
272	    let observations = log.0.into_inner().unwrap();
273	    let mut start = Vec::new();
274	    let mut exec = Vec::new();
275	    let mut post = Vec::new();
276	    let mut timer = Vec::new();
277	    let mut boundary = Vec::new();
278	    let mut failed_exec = Vec::new();
279	    for observation in observations {
