281	            Observation::Start(c) => start.push(c),
282	            Observation::ExecCall(c) => exec.push(c),
283	            Observation::PostExec(c) => post.push(c),
284	            Observation::Timer(c) => timer.push(c),
285	            Observation::Boundary(c) => boundary.push(c),
