109	impl Tool for StopTool {
110	    type GlobalState = Log;
111	    type ThreadState = u8;
112	
113	    fn subscriptions(_config: &Config) -> Subscription {
114	        let mut events = Subscription::none();
115	        events.syscalls([Sysno::getpid, Sysno::write]).rdtsc();
116	        events
117	    }
