119	    async fn handle_post_exec<G: Guest<Self>>(&self, guest: &mut G) -> Result<(), Errno> {
120	        let mode = guest.config().mode;
121	        assert_eq!(guest.regs().await.rip, ENTRY);
122	        assert_eq!(word(guest, WORD), 0, "backend preinit executed guest entry");
123	        guest.send_rpc(Observation::PostExec).await;
124	        if mode == Mode::PostExec {
125	            for _ in 0..2 {
126	                assert!(guest.inject(Getpid::default()).await? > 0);
127	                assert_eq!(guest.regs().await.rip, ENTRY);
128	                assert_eq!(word(guest, WORD), 0, "injection replayed guest entry");
129	            }
130	            assert_eq!(
131	                guest.inject(Close::default().with_fd(-1)).await,
132	                Err(Errno::EBADF)
133	            );
134	            assert_eq!(guest.regs().await.rip, ENTRY);
135	            assert_eq!(word(guest, WORD), 0, "failed injection replayed entry");
136	        } else if mode == Mode::PostExecTail {
137	            // Keep the entry's word observable after Exit. Private ELF data
138	            // alone would lose an erroneous final step when the guest dies.
139	            let fd = guest
140	                .inject(
141	                    Openat::default()
142	                        .with_dirfd(libc::AT_FDCWD)
143	                        .with_path(PathPtr::from_ptr(SHARED_PATH as *const libc::c_char))
144	                        .with_flags(OFlag::O_RDWR),
145	                )
146	                .await?;
147	            let fd = i32::try_from(fd).unwrap();
148	            assert_eq!(
149	                guest
150	                    .inject(
151	                        Mmap::default()
152	                            .with_addr(Addr::from_raw(WORD))
153	                            .with_len(4096)
154	                            .with_prot(ProtFlags::PROT_READ | ProtFlags::PROT_WRITE)
155	                            .with_flags(MapFlags::MAP_SHARED | MapFlags::MAP_FIXED)
156	                            .with_fd(fd)
157	                            .with_offset(0)
158	                    )
159	                    .await?,
160	                WORD as i64
161	            );
162	            assert_eq!(guest.inject(Close::default().with_fd(fd)).await?, 0);
163	            assert_eq!(guest.inject(replacement()).await?, 1);
164	            assert_eq!(guest.regs().await.rip, ENTRY);
165	            assert_eq!(word(guest, WORD), 0);
166	            guest.tail_inject(Exit::default().with_status(27)).await
167	        }
168	        Ok(())
169	    }
170	
171	    async fn handle_syscall_event<G: Guest<Self>>(
172	        &self,
173	        guest: &mut G,
174	        call: Syscall,
175	    ) -> Result<i64, Error> {
176	        let mode = guest.config().mode;
177	        match call {
178	            Syscall::Write(original) => {
179	                assert_eq!(original.fd(), 1);
180	                assert_eq!(original.buf(), Addr::from_raw(ORIGINAL));
181	                assert_eq!(original.len(), 1);
182	                assert_eq!(word(guest, WORD), 1);
183	                guest.send_rpc(Observation::Write).await;
184	                let rip = guest.regs().await.rip;
185	                let result = match mode {
186	                    Mode::Replace => guest.inject(replacement()).await?,
187	                    Mode::SameThenPrivate => {
188	                        assert_eq!(guest.inject(original).await?, 1);
189	                        assert_eq!(guest.regs().await.rip, rip);
190	                        assert_eq!(word(guest, WORD), 1);
191	                        assert_eq!(guest.inject(replacement()).await?, 1);
192	                        assert_eq!(
193	                            guest.inject(Close::default().with_fd(-1)).await,
194	                            Err(Errno::EBADF)
195	                        );
196	                        1
197	                    }
198	                    Mode::TailSame => guest.tail_inject(original).await,
199	                    Mode::TailOther => guest.tail_inject(replacement()).await,
200	                    other => panic!("unexpected write in {other:?}"),
201	                };
202	                assert_eq!(result, 1);
203	                assert_eq!(guest.regs().await.rip, rip);
204	                assert_eq!(
205	                    word(guest, WORD),
206	                    1,
207	                    "next guest instruction ran in injection"
208	                );
209	                Ok(result)
210	            }
211	            Syscall::Getpid(original) => {
212	                if mode.emulates() && *guest.thread_state() == 0 {
213	                    *guest.thread_state_mut() = 1;
214	                    assert_eq!(word(guest, WORD), 1);
215	                    guest.send_rpc(Observation::Emulated).await;
216	                    // Return without injecting. The ordinary callback epilogue
217	                    // must consume the original kernel entry before RDTSC.
218	                    return if mode == Mode::EmulateErrno {
219	                        Err(Errno::EPERM.into())
220	                    } else {
221	                        Ok(123)
222	                    };
223	                }
224	                let expected = if mode == Mode::PostExec { 1 } else { 2 };
225	                assert_eq!(word(guest, WORD), expected);
226	                guest.send_rpc(Observation::Boundary(expected)).await;
227	                Ok(guest.inject(original).await?)
228	            }
229	            other => panic!("unexpected intercepted syscall {other:?}"),
230	        }
231	    }
232	
233	    async fn handle_rdtsc_event<G: Guest<Self>>(
234	        &self,
235	        guest: &mut G,
236	        request: Rdtsc,
237	    ) -> Result<RdtscResult, Errno> {
238	        let mode = guest.config().mode;
239	        assert!(mode.emulates());
240	        assert_eq!(request, Rdtsc::Tsc);
241	        assert_eq!(*guest.thread_state(), 1);
242	        let rip = guest.regs().await.rip;
243	        assert_eq!(rip, guest.config().timestamp_rip);
244	        assert_eq!(word(guest, WORD), 1);
245	        let expected = if mode == Mode::EmulateErrno {
246	            -(libc::EPERM as i64)
247	        } else {
248	            123
249	        };
250	        assert_eq!(word(guest, EMULATED_RESULT), expected as u64);
251	        // Getppid differs from the previously emulated Getpid. A stale Some
252	        // must not send this actual instruction-trap stop through syscall skip.
253	        assert!(guest.inject(Getppid::default()).await? > 0);
254	        assert_eq!(guest.regs().await.rip, rip);
255	        assert_eq!(word(guest, WORD), 1);
256	        assert_eq!(word(guest, EMULATED_RESULT), expected as u64);
257	        guest.send_rpc(Observation::Timestamp).await;
258	        Ok(RdtscResult { tsc: 17, aux: None })
259	    }
260	}
