 223	        &self,
 224	        raw_syscall: Option<unsafe fn(i64, [u64; 6]) -> i64>,
 225	    ) -> Result<PerfCounter, Errno> {
 226	        let mut attr = perf::perf_event_attr::default();
 227	        attr.size = core::mem::size_of_val(&attr) as u32;
 228	        attr.type_ = self.evt.attr_type();
 229	        attr.config = self.evt.attr_config();
 230	        attr.__bindgen_anon_1.sample_period = self.sample_period;
 231	        attr.set_disabled(1); // manual enable, or the initial command exec transition
 232	        attr.set_enable_on_exec(u64::from(self.enable_on_exec));
 233	        attr.set_exclude_kernel(1); // we only care about user code
 234	        attr.set_exclude_guest(1);
 235	        attr.set_exclude_hv(1); // unlikely this is supported, but it doesn't hurt
 236	        attr.set_pinned(1); // error state if we are descheduled from the PMU
 237	        attr.set_precise_ip(self.precise_ip.into());
 238	        attr.__bindgen_anon_2.wakeup_events = 1; // generate a wakeup (overflow) after one sample event
 239	
 240	        let pid = self.pid;
